WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (242::BIGINT, 'Convierte una clase aburrida en interesante. los quices son sencillos pero hay que leer bastante y se esmera en que aprenda lo necesario del curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'bb3f9348e8bfadd70baf1ce4cd03cc479d3712a9b8a94a5f3e7133b982a7cc33'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Es un buen profe, le tiene paciencia a uno y no califica duro. Explica bastante bien y si ud lo necesita le vuelve a explicar hasta que ud entienda. Es muy comprensivo y busca soluciones para prácticamente cualquier problema que tenga.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-07T00:00:00+00:00'::TIMESTAMPTZ, '44954a72565b2f48c572048d1781c2f3d76a0bd57809c8be4c35ee1113470928'::TEXT, ARRAY[610]::BIGINT[]),
    (242::BIGINT, 'Se nota que le apasiona lo que hace y trata de explicarlo de manera totalmente clara para que el estudiante lo entienda. Logra que una materia aburrida se vuelva interesante. Los quices son muy directos pero sencillos. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '26734b91a41b20ba3d10869eef59cb94563cfb01d53ce011ef1baf9bd5649639'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Sabe demasiado y explica excelente, las clases son largas y cansadas pero valen la pena, la materia de por si ya es difícil entonces con cualquiera es complicado, califica a como explica. No regala puntos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2024-12-13T00:00:00+00:00'::TIMESTAMPTZ, '62aa28141fc3f3c42873ea80585c497b8d923e992fcf021836e9d2d181fde2eb'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Da igual si matricula el curso con Felipe o con él. se lo va a topar igual. Dicho esto en general es buen profe. Explica super bien y se esmera en que uno aprenda de verdad. Lastimosamente califica bastante binario y los quices son horribles (solo tienen 2 preguntas) pero igual es buen profe.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes']::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, '4f106730451941665e9089f0e5b25f09f88322112fa2470d1b37f1733f31c0fe'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Buen profesor. Se nota que tiene buena experiencia laboral. Tal vez, para el curso de Dibujo técnico sus clases presenciales son un poco rápidas, pero a nosotros nos daba vídeos para consultar en casa y era de gran ayuda. Igual explica bastante claro y al grano.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0ddc49802cf62a60b0b937e56b660ad72a4326699bed0f7f546ee8b9cfd9026d'::TEXT, ARRAY[610]::BIGINT[]),
    (242::BIGINT, 'Explica bien, buen profe. no regala puntos'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'd51d146fd279b35c3bb6c6a69ab27711db35973c7dacc5ac25b33bedafac6feb'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Con este profe se lleva la mitad del curso. Hace quizzes de dos o tres preguntas basadas en el curso entonces hay que tener mucho cuidado respondiendo. Además los quizzes valen demasiado en este curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b39d2982186842c299599daa9087313b0382fd8c2913da50c494a5101df1f217'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'El curso en sí es duro y hay que estudiar bastante pero el profesor explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '09f0c8459c81615f0d342248bd5c0d434f2f80026981a55cf2ba46633d777ac3'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'El curso por si solo es complicado, en especial si no se tienen muchos conocimientos sobre el tema, pero el profe explica bien, va paso a paso y ayuda si los estudiantes no estan entendiendo, si hay que practicar y estudiar bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '75fab944c7081d1f7fd8bd4d5f39f80ae3807ce7cccc6ab044bb3458172cfa64'::TEXT, ARRAY[610]::BIGINT[]),
    (242::BIGINT, 'El profe es serio pero muy amable. El curso es complicado (estudie bastante), pero revisando el material antes de la clase, poniendo mucha atención, participando en clase y yendo a consulta el curso se pasa bien. Estudie bastante para los quices, la rúbrica con la que califican es muy grosera.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'cff5c5ee8ae91bea2a52f9e2a0aff49a86e3c116cf302d00be5ca1f9f475c6b4'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '08716c9bf0bc5afd1e350a777281d4c45b14fe4d7da6846b96f4f9d77ddd1fcf'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'No sé en cursos más avanzados, pero en este, ni fu ni fa, la verdad es un bastante desordenado y las clases no se porque se suelen hacer bastantes aburridas (Precisión) , califica suavecillo y las evaluaciones suelen ser normales.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '5542879b3c2c67f13d72a07a12b6e835c3bc194da4650ebc9920c975aaa17c5f'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'El profe es buena nota y ayuda bastante en cuanto a las consultas, pero a veces siento que explica muy rápido y se salta bastantes pasos importantes, por lo que a uno le queda la duda. El curso es bastante difícil, por lo que hay que dedicarle bastante, sin embargo no califican tan rudo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, '96c3b8f484952d8ec91d30dcecc879e3a0a5d9a2b12bda8b2bca12011d1ffc7b'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'El curso por si solo es dificil pero este semestre lograron hacerlo pasable si se estudiaba moderadamente, explica bien y toma su tiempo en que se entienda el tema. El unico detalle es que entrega algunas evaluaciones un poco más tarde de lo esperado y algunas son bastante dificiles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5bad7a9723ace0aef26d433ad896677be8412b8074c5a3a96f01e6ac213a8fc2'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'El curso por si solo es complicado, es bastante dificil, el trata de ayudar en lo que puede. Hacerle reclamos es un dolor porque nunca los revisa, hay que insistirle. En clase el mae copia los ejemplo del Ipad, entonces se salta algunos detalles de la resolucion, en cosulta ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9656b7dd91caff5f5aabc07e5184050f5d5b15ad5cb331111bd7d926716a7226'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Dinámica es bastante difícil y el profe no lo empeora, pero tampoco lo mejora. En clase casi que solo hace ejercicios entonces hay que ir con la teoría leída del libro. Hay que estudiar mucho. Otárola a veces es muy tosco y no tiene compasión con las matadas que uno se da a lo largo del semestre.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c3a1c1fba9b791d49ea0c716867a20027c1be2ec75e2ec012e113091ce0a0236'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Se tiene que llevar con los dos profesores que dan este curso, que se divide en dos módulos, un prof para cada módulo (precisión-soldadura). Otárola sabe que este curso es una introducción a conceptos demasiado complejos, y hace la clase interesante y poco difícil. Hay que estudiar para los quices.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2023-01-10T00:00:00+00:00'::TIMESTAMPTZ, '4e1cb663d1ae174eae11beb87c5d919dcfafaebfbd907708e7ee081878d0db03'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'En clase explica bien, hay que estudiar del libro para llegar a la clase y seguir el hilo de la explicación, para el proyecto recomiendo que asistan a consulta, ya que da recomendaciones y les da ideas con la simulación de SOLID, lo recomiendo es ordenado para dar las clases.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '74e012f85ff4dbb0299d1f7466a24e05c423f045e360b8cbf3b6ce1fab41fd1d'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3bf1536cd53b02104224e04de4441fbac5314708eab21d3c64466ab480c1880c'::TEXT, ARRAY[610]::BIGINT[]),
    (242::BIGINT, 'El prof en general es bueno. Lo que tiene en comparación a otros profes de la escuela de electromecánica es que el mae es ordenado al dar la clase. Y la verdad eso ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'dd876b3699aaffc67d01016e004516046bafd6b7df5d9b3a66cbdbd8166005dd'::TEXT, ARRAY[931, 641]::BIGINT[]),
    (242::BIGINT, 'Muy malo, de profesor no tiene nada, no ayuda, no contesta mensajes, explica mal. Anda en otras, los quices o examenes siempre tienen problemas para realizarse (virtual)'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5816c95e448a949e7d3f99f58aad30557869fca79f1b42f974a7b5bdf9ab9be1'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'El profe explica bien y si uno tiene dudas se las contesta, pero las clases se hacen eternas y los quizes son un poco complejos, a pesar de todo no es una mala opción'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '82de662307c7aae47aa428055b0865230d1e6f945d92ae80d2d592d868d70681'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Quices cortos, pero complejos. Las clases se hacen eternas y se gasta mucho tiempo hablando de otras cosas por lo que es fácil perder el interés. Lo más fácil es estudiar del libro y buscar puntualmente cada pregunta del quiz porque lo que pregunta no se relaciona a lo explicado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, '042f1bafc77117c6f0d8fc567a1374b5033086bb704da619a803dda16dcd1374'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'El curso como tal es complicado, pero en pandemia se hizo más llevadero al no haber exámenes. El profe deja quices todas las semanas y cuesta mucho que le responda a uno, ya que los canales de comunicación son reducidos. En general, es un buen profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'ae817e34195356f8a1ce57a32d8fa5b9ba642852ab215433ac818085449e1724'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Realmente es un buen profe, lo que pasa es que la materia en sí es difícil de explicar. Los ejercicios que se desarrollan son muy largos, entonces se vuelve pesado, pero él trata que uno entienda.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3e262a2fc4b054e25bf1ba0f9c5c52d438cc4aa25247f08cf19faf041e0081e7'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Proyectos que pueden ser complicados o no individuales, la materia es muy confusa aunque el se esmera que uno en verdad entienda, se toma su tiempo pero se vuelve agotador al rato de estar en la clase. Buen profe de necesitar en vrdd que lo va ayudar y es comprensivo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4d7723f613d757ca75dc2347a8c46e2c18653d39bb977414c4b846e815d6f6ad'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Buen profe, es comprensivo con las entregas y ayuda en lo posible. Sus clases son bastante confusas sobre todo al final del curso, pero siempre tienen algo que ver con lo que él evalúa.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1d31e91cff3b5797bf7032ecd34aff22013abf6ff6d56ae16cc501b6f9e09ab5'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Muy buen profe en general, explica claro. Para los quices prácticos en dinámica deja usualmente varios días; las clases si suelen ser largas pero da recesos. Si cuesta un poco que responda fuera de las clases. Volvería a matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, '4ac8c6ef5c20d44831da2b46c7342fcb7aae7a7a90cafcf20f1ac647c6bb30f5'::TEXT, ARRAY[931, 641]::BIGINT[]),
    (242::BIGINT, 'Este profe es malo, explica bien y es ordenado, pero de nada sirve, los quizes son a dañar y las instrucciones inentendibles. Además que califica durísimo, en el curso se puede eximir le aconsejo por su bien que lo haga, igual si lleva procesos se lo traga por que solo el da el modulo de Precisión'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '575cc5f2d3d8578a214372f34dd79bfebd5c31f575242e8a16b096b60bd65c09'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Generalmente es un buen profe, que explica bien la materia, y apoya cuando uno tiene dudas. Regularmente hace quizzes (casi todas las semanas), y en clase explica bien la teoría. A veces no deja instrucciones 100% claras, o dura mucho explicando algún tema, pero solo es preguntarle y aclara todo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c86518cc921cc5ee0caecc954c0aeaa3b5027676c94384dbdbb3bb99ae71e524'::TEXT, ARRAY[947]::BIGINT[]),
    (242::BIGINT, 'Clases demasiado aburridas, quices sorpresa y algunos con poca claridad en las instrucciones Se pasa'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '081e3011323737bc765f8031562acae0118b498ad83e7ed4152025cf8cf0a7d5'::TEXT, ARRAY[945]::BIGINT[]),
    (242::BIGINT, 'Virtual. Muy buen profe, usted literalmente va a Aprender y además hace que uno se interese mucho por la clase. Brinda ayuda y organiza muy bien las lecciones. Dele sin miedo a matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'e486d1c18f88234db76026f91b1cdc12213b29da7549fda2208b86b77b4616cc'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Buen profe, la verdad el mae es muy accesible en consulta y explique cuantas veces sea necesario... además uno aprende bastante :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '20fdb56565064dc645e11c1d21b8792b81aaa5d31f6886d37eef3457f5912f0e'::TEXT, ARRAY[945]::BIGINT[]),
    (242::BIGINT, 'Es buen profe. No es nivel Chevez pero igual uno aprende. Explica las veces que sea necesario con toda la disposición del mundo. Los quices que deja son rudillos y a veces se queda trabado en algún ejercicio. Igual lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'b6352dafaf0d034c7b57fbe7fd9401ec30777f447171f1e2e200dbc29c4ae6eb'::TEXT, ARRAY[947]::BIGINT[]),
    (242::BIGINT, 'Es buen profe, explica ejemplos de examen. Siempre explica cuando se le pide (ahora en modo virtual) hasta que usted comprenda y no es tan rudo calificando.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '8a31cd69c507134bc1a7bde0dd27c5fbe698d28e63c35bc48fe782d390f8b045'::TEXT, ARRAY[947]::BIGINT[]),
    (242::BIGINT, 'Es muy buen profe lo recomiendo, la clase es un poco larga pero interesantes, el algunas ocaciones deja tareas largas pero si se aprende bastante, deja trabajos de puntos extra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'd225d812351682f2b1eed6c240a5fe347576404dd33c12a135083f6b2e9afe10'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Califica como si enseñará como Chevez y a diferencia de este pasa confundiéndose en clases, con este profe da muy poco tiempo para los quices y parecen problemas de examen.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd21a82ef4a6786deffe481227579fcacdbc63e6c0280b07c0cedac35b480d3e2'::TEXT, ARRAY[947]::BIGINT[]),
    (242::BIGINT, 'Quizas la primera que dió dinamica no fue la mejor pero la segunda fue excelente super claro, quices relativamente sencillos a menos de que seas un completo ignorante, enseñaba dinamica como debe ser no unicamente hacer ejercicios y no saber lo que que se esta haciendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-26T00:00:00+00:00'::TIMESTAMPTZ, '66386073f80d2252fe45f8b323445797ce05cf451b907025038901a0ec4087df'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'La verdad, no metería el curso de nuevo con él, se pegaba en ejercicios hasta clases enteras, y los que resolvía los tenía malos, bastaba con ver el solucionario para saber que estaba mamando. Tenía que ir a consulta con otros profes el mae no domina la materia. Una pérdida de tiempo. Espero mejore'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '81c8cdb3fb368a70055a4b6f6af6af330ccf7841ce1bbb9f8d4b5c7ece1d7566'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'Es bueno explicando los primeros temas, luego se enreda y dura una clase entera pegado en un ejercicio. Los quices son relativamente dificiles.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7faeff067689cc6d73407f0674bc7cb1555a4ce7f98537222306c46b3023ead9'::TEXT, ARRAY[947]::BIGINT[]),
    (242::BIGINT, 'Es estricto, pero si se sabe hablar con él es bastante flexible. Lo recomiendo full. Es una excelente persona y profe. Industrial es difícil con cualquier profe, de todas formas.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'f842f220390f60d2e71a19f15ef37af2d044975a839329af4f8a50494f41eccc'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Es la primera vez que da el curso por lo que la materia no la dominaba. Se enredaba al hacer los ejercicios y para peores duraba mucho desarrollándolos, por lo que al final hacía pocos ejercicios. Los quices que hizo fueron relativamente difíciles.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'aa5a056757b25e1c74b300b2c807a1929fea6b0d9079bbdcea4b33e9ce510447'::TEXT, ARRAY[931]::BIGINT[]),
    (242::BIGINT, 'El profe es muy accesible, es estricto sí, pero explica bien y se preocupa por el estudiante. Es buena gente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '76e8f8910f91f9389e3e0238928eef66da4adae0e72204737abbc265cd97a538'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'El mae sabe y cae bien. La clase es entretenida si a usted le interesa, pero el mae es muy desordenado, deja 2 tareas muy tediosas, con instrucciones no tan claras que solo en consulta se resuelven. El mayor problema es con los quices, en los que hay que leer como 40 paginas para 4 hps preguntas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6ae926c6823d35af5ad5fd2f1f34848de9a66f060903d1ef3ea8fcd94c440ebf'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2018-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a81816bd54bef6b13ab451c535c91665ecf286fe64017731ae5586abcfc0ef36'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '59758ad183189be2bf2dcb6fad8d5d21561e61bfad1bb04c857dd69cd3bea421'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Califica cada detalle. Es buen profesor. La clase se puede hacer un poco pesada pero explica bien. Ayuda y aclara cada duda que se le pregunte.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a1447ff5017ae3a77ba4e4897d209854e97aa21f82f44b6d36c85e23a9a687e2'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Es buen profe a la hora de explicar pero es un poco egoísta pues no pasa las presentaciones aunque se las pidan, también es muy rudo a la hora de calificar pero es el único que da precisión so... Y prepárece para leer y tragar materia si quiere ir bien en los quices'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'b28b8783055bcb531c0196d75ad8bf0b4c9f77544a6ca6e374cab942520b9a3e'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Confuso y difícil de seguir, las clases son largas y aburridas. Muy exigente en los proyectos. Las instrucciones de los trabajos no son claras, por lo cual se pierde puntos inesperadamente. Las lecturas son largas y los quizes son de pura memoria.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, '722ac01b8559ce8efac1cfaf421482bc287c3e7415c788862b0763cd3bdcbe92'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'La clase es un poco pesada pero es llevadera, hace quices todas las semanas por lo que hay que llevar la materia leída al día. Ni bueno ni malo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'c6e50f80e5a1d3646ba3f9e6594965f28dfdf69d054a1364a64c23d11bbfc01f'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Excelente profesor, las lecturas se deben de llevar al día, exigente en quices y sobre todo en el proyecto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'f2185477276b274e959265c665141d20175d1d558ca3b166562b0d444b317a8d'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Es un profe serio, a veces no tiene la mejor actitud pero en general tiene disposición de explicar la materia, sabe mucho.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5db8be7044c08165dec83357ec17cf1a53e3738afea23d76c9016f379989efc9'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Muy aburrido y hace evaluaciones muy duras. Exige demasiado para lo que enseña.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'a9f2ffb95f8fcc6c638ddeb6ac0b760bfa75b376b57bde145f7204e1d2218c39'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Aunque en ocasiones se confunde, ayuda bastante y explica las veces que sea necesario.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '150ebe913f7aa8b55ef12dbde9026ddaba2119bf6fdcc87916a5f54ee449de7c'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Evaluaciones dificiles y las califican duro, es claro y explica, cumple como profesor. En general es prepotente, muchas veces se enreda y no queda claro, asume que tienes todas las bases claras. Critica mucho al estudiante de la formación que recibe. No es malo pero hay presión en el curso con él.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2017-07-30T00:00:00+00:00'::TIMESTAMPTZ, '53765cc646bb82e7cc4d7bc69144cf06d93b8006346e0df179184ad11b109f47'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Buen profesor, explica bien, si usted busca ayuda el se la da, es ordenado y como persona es pura vida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo']::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, '41b324f61ce8cc58ed7717d53ca9ea49237ed9c011c80719070ba74335023b34'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'No es el mejor pero se defiende. Si uno le pregunta él explica, a veces se enreda pero si se da a entender. Muy distraído y hay que estar detrás de él porque todo se le olvida pero cuando uno muestra interés ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '962267ddb6ba813340e7701abd86a9306762611297639b346e92edd94153adf6'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Es muy buena persona, super amable y educado, explica muy bien. Es muy ordenado en sus lecciones. La verdad no hay nada malo que recalcarle a este profe, un excelente profesional!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f80ee7dd7842ff2a84d3456d862f5697beddce50676690cbcd029ad199e7fed3'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '070e6fe353a1cff77fa4a0b9f97ba6970a7f061d214e8ac286ca91d566d7d527'::TEXT, ARRAY[1854]::BIGINT[]),
    (242::BIGINT, 'Explica muy bien y es muy ordenado. Es bastante estricto'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c979bfed91150324387073102161eec7390480efbf8fcd369c6e7aeeb97a095d'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Es un profe muy bueno; sabe explicar muy bien, interesado en el aprendizaje del estudiante, califica muy justo, quices normales, además de que es muy correcto y respetable. Es un poco serio. Excelente profesor !'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'd3e571893f54cbcc084a716a26fe4e9baed23dec5444afc508016c5426eec5e2'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Muy buen profe, hace que las clases sean diferentes y califica normal, los quices son pasables y uno aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ee5760cd66374a5a06072a09fc4cc5aa78baac948b229c5956c7718c11fe1d69'::TEXT, ARRAY[641, 931]::BIGINT[]),
    (242::BIGINT, 'Hace el curso difícil pero muy interesante. Las evaluaciones son exigentes, como debe de ser. Muy buen profe.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '256e18efc6f9c71904781ee5a13d696aa8d1a9e07af13d2bc1a1dab858e9e91f'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Nació para ser profe. Buena persona y se preocupa por el aprendizaje. No es fácil pasar sin esforzarse. No envía las presentaciones y exige mucho en el proyecto, que quita tiempo. En general, un profe excelente y da gusto llevar con él. Sabe mucho, y se gana el respeto. Si le pone, pasa sin problema'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'c036151aa3dd3e9b175e94bcbaf372c1605051a2788eb7b6cdfafbee9bd0c707'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Si las lecturas se llevan al día, no hay problema con los quices, muy exigente en el proyecto y el examen es pasable. Es muy buena gente y ayuda muchísimo, se nota que se preocupa en que uno entienda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '00c289cc63566e63749764e0e3afcb5169cf865bfb882082f0eddc3f2fc58966'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Explica muy claro y las veces que sea necesario. Es muy justo, califica de acuerdo con lo que Ud. se merezca, y lo mismo con los reclamos (no regala nada pero tampoco es que ponga 0 por todo). Quices intermedios.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd9f7d38ce3628da86cdcd33eda3291c30edee9177d82ac558aa5daae5893644b'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Muy bueno explicando realmente lo prepara para los exámenes, los quices son regulares y hace que el estudiante se interese en la materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '08177cade95aa18a85f4bdfd3b8f9f689447bb01338b4a6428b56b0441c90266'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'El curso es MUUUUYYY duro y pesado, llévelo con algo fácil. Le va a quitar mucho tiempo y horas de dormir. En cuanto al profe, era la primera vez que lo daba, a veces se perdía un toque, pero nada fuera de los normal. Realmente califica suave las tareas y ayuda mucho, si va a consulta le explica más'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '007e8267995ecb5fb804be7db3d2f2731061b706647cacdc3bf654bf1811d153'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Excelente profesor en todos los aspectos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '68b2eb881f0d29fee5cc42801a9878ef5641e8c92078634f3eddb7fa13b7f203'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Super recomenado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '198b065ab23ea5f9514433ac53b3089444dee3bcca8df823bd8b9d0c21320d5a'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '60df41b914a01c2dbc4d9cf72bf90cbcea54d0c990398c7943df2cd730aec7a0'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Para ser la primera vez, se la jugó. De por sí este curso es durísimo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'afa679a2d42fa4225ec62390e1a7345e1c9e8fb6a6af6f62543dc4817596eb31'::TEXT, ARRAY[934]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '93d3075dd63fead88d64919436053c373bf0ff74cd34d33e517428bbef39a149'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Los quices son duros, es muy exigente en los proyectos, pero explica muy bien, ademas ayuda bastante'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'b89b7bcb981b7b88c24b900b7b36bf02d132e1fd3911426582ed145d57a77f18'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-03-16T00:00:00+00:00'::TIMESTAMPTZ, '8ffaddf886fe2168fc194c03a9ea342f78eadeb27cfd5539830fc615ba5405b3'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'El mae es bueno. no sube las presentaciones que ve en las clases y los quices durillos. Pero ayuda mucho.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '91f54cfb2ea7fd576fd7e368a1da548b7a479a0eda1e572b952471653b65d0da'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Es un profe exigente pero creo que al nivel que se debería en una universidad, siento que es profe por vocacion'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '55a74e6fed98b904ef48a7ccc25679c1ab2bec83ec3d24b9c39e7664b0d5e0e8'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'caf90ddfcada1dab9a90cbf79a31fc3ba90879c7155d288a84142d3743482145'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'El profe sube las presentaciones y ejercicios que va a realizar en cada clase desde la primer semana. Si se organiza, puede aprovechar cada clase. Los quices son fáciles pero tramposos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '35d0ff4e36f26476edd526772fc1b4f543c25335b592196cd81640fde33d539d'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Es exigente, hace muchos ejercicios pero a veces se enreda y no sabe como arreglar el enredo. Hace muchos quices, pero hay varios que si requieren trabajo extra.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, '11094d7ada333b62ea9bd2e667ea232cda06d14815a5d00ee1c92f94de2f4a68'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Muy bueno y organizado! Exige bastante eso sí.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'ad984fd4bac51e67e6dc387631fca106b7a178ed0aa4856e52acbe52a3d672df'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Se enreda mucho cuando explica y busca la solución de los problemas en el solucionario lo cual no da una buena imagen'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '46d4b47c5071b6f6b5978c555a699a21c0b9970b57262c139dbacb478411bc84'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Sabe y explica bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-26T00:00:00+00:00'::TIMESTAMPTZ, '2df4b46286aafe12fe1ea8c7b8e39be6daa8634c140046c62f85002273cd0d3b'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'En Procesos, cuesta mucho quedarse. En Estática es malo, pero no el peor. Se enreda solo y cuando se enreda, que es casi siempre, no sabe como corregir lo que está haciendo y enreda a todo mundo. Quices fáciles.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'cbe828464331ddb9b11008b365c857a9ecba36e8ceaca2021e1ae218e17bb667'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Explica muy bien pero es un dolor. Califica muy fuerte, y los quices son muy rudos. No sube las presentaciones entonces hay que escribir rápido. Exige mucho. Casi nunca está en el aula (solo en algunas horas de consulta). Es muy puntual. baja puntos por mala ortografía...'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '62e55f91b98a6fcf4619e9cfc0fa2a0976dedd1c0549b4e63dc2083ba4a3bfee'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '7a05b27a05782922da9eea7803da3e74c570c9989b4a8302394d8ea6d08780c1'::TEXT, ARRAY[1726]::BIGINT[]),
    (242::BIGINT, 'Muy bueno, siempre claro y dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '333bfb4e007c1e1531a2daaedca45fd2570d5fb468f97bd873a92bbce4b977a5'::TEXT, ARRAY[610, 641]::BIGINT[]),
    (242::BIGINT, 'grupo unico,'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2a56f5c61a9e570b65e833350f2ee022945a21f196db9fc5c78109031d37ed3c'::TEXT, ARRAY[641]::BIGINT[]),
    (242::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'eea2abd751e767a18a72f91b0838f4ebe292cee84cc24c4d140fe0fcbe2d6989'::TEXT, ARRAY[1726]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
